//! ESP32-C3 / esp-hal code generator.
//!
//! Generates and splices the GEN_BEGIN … GEN_END block for ESP32-C3 projects.
//! The HAL version is not written here — the header line is built from
//! [`ESP_HAL_REQ`](crate::panels::mcu_module::project_gen::ESP_HAL_REQ), the same
//! constant `Cargo.toml` is generated from. Structure of a generated
//! `src/main.rs`:
//!
//! ```text
//! // Auto-generated by Embedded IDE
//! // MCU: ESP32-C3 | HAL: esp-hal 1.1.0 (blocking)
//! // embedded-ide:mcu=esp32c3
//! #![no_std]
//! #![no_main]
//!
//! // <<< GENERATED BEGIN — do not edit between these markers >>>
//! use esp_hal::gpio::{Level, Output, OutputConfig};
//!
//! #[esp_hal::main]
//! fn main() -> ! {
//!     let peripherals = esp_hal::init(esp_hal::Config::default().with_cpu_clock(esp_hal::clock::CpuClock::max()));
//!
//!     // ── GPIO ──
//!     let mut gpio2_out = Output::new(peripherals.GPIO2, Level::High, OutputConfig::default()); // GPIO Output
//!
//! // <<< GENERATED END >>>
//!     loop {
//!         // Your main loop code here.
//!     }
//! }
//! ```
//!
//! The [`Runtime::Async`] path emits the same body from the same builder — only
//! the entry point differs (`#[esp_rtos::main] async fn main(Spawner)` plus the
//! `esp_rtos::start(...)` scheduler hand-off). See [`EspRuntime`].
//!
//! [`Runtime::Async`]: crate::panels::mcu_module::mcu::Runtime

use super::clock::ClockConfig;
use super::clock::graph::evaluate;
use super::codegen::{GEN_BEGIN, GEN_END, mcu_id_marker_line, pin_binding, sanitize_label};
use super::modules::{I2cModuleConfig, SpiModuleConfig, UsartModuleConfig};
use super::pins::logic::pin::Pin;
use super::pins::logic::pin_function::PinFunction;
use std::collections::{BTreeMap, BTreeSet};

// ── User tail — closes fn main() ─────────────────────────────────────────────

const USER_TAIL: &str = "    loop {\n        // Your main loop code here.\n    }\n}\n";

/// First link of every esp-hal bus builder chain: `Uart::new` / `Spi::new` /
/// `I2c::new` all return `Result<Self, ConfigError>` on esp-hal 1.1, so the
/// `.with_xxx(...)` links below them do not exist until it is unwrapped.
///
/// A bad config here is a programming error the IDE wrote (the values come from
/// the Virtual Module UI, which range-limits them), not a runtime condition the
/// firmware could handle — the same reason the STM32 backend emits
/// `pac::Peripherals::take().unwrap()`.
const UNWRAP_CFG: &str = "\n        .unwrap()";

// ── Runtime (entry point) ────────────────────────────────────────────────────

/// Which entry point the generated `main` opens — the only structural difference
/// between the two ESP paths. Everything below the entry (clock, GPIO, UART,
/// SPI, I2C bindings) is byte-for-byte identical: they are the same esp-hal
/// drivers, so one builder serves both.
///
/// Async is `esp-rtos`, NOT `esp-hal-embassy`. The latter is pinned to esp-hal
/// 1.0 by the private `__esp_hal_embassy` feature, which esp-hal 1.1 (what the
/// project template pins) no longer has — the dependency resolution fails before
/// anything compiles. `esp-rtos` is the same maintainers' replacement and drives
/// the very same `embassy-executor` / `embassy-time`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum EspRuntime {
    /// `#[esp_hal::main] fn main() -> !`
    Blocking,
    /// `#[esp_rtos::main] async fn main(_spawner: Spawner)`, with the scheduler
    /// started from TIMG0 + software interrupt 0.
    Async,
}

impl EspRuntime {
    /// The attribute + `fn` signature line(s) that open `main`, ending in `{\n`.
    fn entry(self) -> &'static str {
        match self {
            Self::Blocking => "#[esp_hal::main]\nfn main() -> ! {\n",
            Self::Async => "#[esp_rtos::main]\nasync fn main(_spawner: Spawner) {\n",
        }
    }

    /// The lines that hand the timer to the scheduler, emitted right after
    /// `esp_hal::init` — empty on the blocking path.
    ///
    /// TIMG0 is the timer the esp-rtos docs (and `esp-generate`) use; taking it
    /// here means user code cannot also claim `peripherals.TIMG0`, which is the
    /// normal trade for having `embassy_time::Timer` work at all.
    fn start_block(self) -> &'static str {
        match self {
            Self::Blocking => "",
            Self::Async => {
                "\n    // ── Async runtime (esp-rtos drives the embassy executor) ──\n\
                 \x20   let timg0 = TimerGroup::new(peripherals.TIMG0);\n\
                 \x20   let sw_int = SoftwareInterruptControl::new(peripherals.SW_INTERRUPT);\n\
                 \x20   esp_rtos::start(timg0.timer0, sw_int.software_interrupt0);\n"
            }
        }
    }

    /// The extra `use` items the async entry + scheduler start need.
    fn use_lines(self) -> &'static [&'static str] {
        match self {
            Self::Blocking => &[],
            Self::Async => &[
                "use embassy_executor::Spawner;",
                "use esp_hal::interrupt::software::SoftwareInterruptControl;",
                "use esp_hal::timer::timg::TimerGroup;",
            ],
        }
    }
}

// ── Clock config → esp-hal `CpuClock` ─────────────────────────────────────────

/// The `esp_hal::init(...)` line, with the CPU clock taken from the clock graph.
///
/// esp-hal exposes only `CpuClock::_80MHz` / `_160MHz` for the ESP32-C3, so the
/// graph's `cpu` node (160 MHz on the ÷3 divider, 80 MHz on ÷6) maps to those.
/// When the chip has no graph clock the line falls back to `CpuClock::max()`,
/// matching the previous hardcoded default.
fn esp_init_line(clock: &ClockConfig) -> String {
    let cpu = match clock {
        ClockConfig::Graph(gc) => {
            let cpu_hz = evaluate(&gc.graph).get("cpu").copied().unwrap_or(0);
            if cpu_hz >= 120_000_000 {
                "esp_hal::clock::CpuClock::_160MHz"
            } else {
                "esp_hal::clock::CpuClock::_80MHz"
            }
        }
        ClockConfig::None => "esp_hal::clock::CpuClock::max()",
    };
    format!("esp_hal::init(esp_hal::Config::default().with_cpu_clock({cpu}))")
}

// ── Public entry points ───────────────────────────────────────────────────────

/// Build a brand-new `src/main.rs` for an ESP32-C3 project.
/// Called when the MCU type is first selected or the project is reset.
pub fn fresh_esp32c3_main_rs(
    pins: &[&Pin],
    clock: &ClockConfig,
    mcu_name: &str,
    id: &str,
    usart: &BTreeMap<u8, UsartModuleConfig>,
    spi: &BTreeMap<u8, SpiModuleConfig>,
    i2c: &BTreeMap<u8, I2cModuleConfig>,
    custom_inits: &str,
    runtime: EspRuntime,
) -> String {
    let section = make_gen_section(pins, clock, usart, spi, i2c, custom_inits, runtime);
    format!(
        "{}{section}\n{USER_TAIL}",
        invariant_header(mcu_name, id, runtime)
    )
}

/// Replace only the GEN block inside `existing`, preserving the user's loop body.
/// If markers are not found, rebuilds from scratch.
pub fn update_esp32c3_main_rs(
    existing: &str,
    pins: &[&Pin],
    clock: &ClockConfig,
    mcu_name: &str,
    id: &str,
    usart: &BTreeMap<u8, UsartModuleConfig>,
    spi: &BTreeMap<u8, SpiModuleConfig>,
    i2c: &BTreeMap<u8, I2cModuleConfig>,
    custom_inits: &str,
    runtime: EspRuntime,
) -> String {
    let new_section = make_gen_section(pins, clock, usart, spi, i2c, custom_inits, runtime);
    if let (Some(begin), Some(end_start)) = (existing.find(GEN_BEGIN), existing.find(GEN_END)) {
        let end = end_start + GEN_END.len();
        // Strip ALL leading newlines after GEN_END, then re-add exactly one
        // blank line so splice is idempotent (same as the STM32 path in codegen.rs).
        let after = existing[end..].trim_start_matches('\n');
        // The region above the markers is the USER's (their own `use` items, their
        // panic handler) so it is kept as-is — except the one provenance line,
        // which is ours to keep truthful.
        let head = refresh_hal_line(&existing[..begin], mcu_name, runtime);
        format!("{head}{new_section}\n{after}")
    } else {
        // No markers — rebuild from scratch.
        format!(
            "{}{new_section}\n{USER_TAIL}",
            invariant_header(mcu_name, id, runtime)
        )
    }
}

// ── Invariant file header ─────────────────────────────────────────────────────
//
// Written once on project creation. Only the `// MCU: … | HAL: …` provenance
// line is refreshed afterwards (see `refresh_hal_line`) — everything else above
// the markers may have been edited by the user and is left alone.

/// First line of a generated file, and the anchor the provenance line is
/// inserted after when an older file has none.
const AUTOGEN_LINE: &str = "// Auto-generated by Embedded IDE";

/// Marker the provenance line starts with, so it can be found and rewritten.
const HAL_LINE_PREFIX: &str = "// MCU: ";

/// The `// MCU: … | HAL: …` line: which chip, which HAL **version**, which
/// runtime. Both versions come from the constants `Cargo.toml` is generated
/// from, so the comment cannot drift from the dependency it describes — the way
/// a hardcoded "esp-hal 0.22" kept claiming 0.22 on a 1.1 project.
fn hal_line(mcu_name: &str, runtime: EspRuntime) -> String {
    // "~1.1.0" / "^1.1" / "1.1.0" all describe the same release series; show it
    // without the requirement operator.
    let hal =
        crate::panels::mcu_module::project_gen::ESP_HAL_REQ.trim_start_matches(['~', '^', '=']);
    let rtos = crate::panels::mcu_module::project_gen::ESP_RTOS_REQ;
    match runtime {
        EspRuntime::Blocking => {
            format!("{HAL_LINE_PREFIX}{mcu_name} | HAL: esp-hal {hal} (blocking)\n")
        }
        EspRuntime::Async => {
            format!("{HAL_LINE_PREFIX}{mcu_name} | HAL: esp-hal {hal} + esp-rtos {rtos} (async)\n")
        }
    }
}

/// Rewrite the provenance line inside `head` (everything above `GEN_BEGIN`), or
/// insert it when the file has none — an older project keeps advertising the HAL
/// it was BORN with, and a runtime switch would otherwise leave "(blocking)" on
/// an async file. Idempotent: re-running on its own output changes nothing.
fn refresh_hal_line(head: &str, mcu_name: &str, runtime: EspRuntime) -> String {
    let wanted = hal_line(mcu_name, runtime);
    let mut out = String::with_capacity(head.len() + wanted.len());
    let mut done = false;
    for line in head.split_inclusive('\n') {
        if line.trim_start().starts_with(HAL_LINE_PREFIX) {
            if !done {
                out.push_str(&wanted); // replace in place, keeping its position
                done = true;
            }
            continue; // drop duplicates from older revisions
        }
        out.push_str(line);
        if !done && line.trim_end() == AUTOGEN_LINE {
            out.push_str(&wanted);
            done = true;
        }
    }
    if !done {
        // Neither a provenance line nor the autogen banner (a file the user
        // rewrote from scratch) — put it at the very top, where it reads.
        out.insert_str(0, &wanted);
    }
    out
}

fn invariant_header(mcu_name: &str, id: &str, runtime: EspRuntime) -> String {
    format!(
        "{AUTOGEN_LINE}\n\
         {hal}\
         {id_line}\
         #![no_std]\n\
         #![no_main]\n\n\
         pub mod pins;\n\n\
         \n\n\
         esp_bootloader_esp_idf::esp_app_desc!();\n\
         #[panic_handler]\n\
         fn panic(_: &core::panic::PanicInfo) -> ! {{\n\
             loop {{}}\n\
         }}\n\n\
         ",
        hal = hal_line(mcu_name, runtime),
        id_line = mcu_id_marker_line(id),
    )
}

// ── Generated section builder ─────────────────────────────────────────────────

fn make_gen_section(
    pins: &[&Pin],
    clock: &ClockConfig,
    usart: &BTreeMap<u8, UsartModuleConfig>,
    spi: &BTreeMap<u8, SpiModuleConfig>,
    i2c: &BTreeMap<u8, I2cModuleConfig>,
    // Custom-module `let x = Foo::new(…);` lines (see `Mcu::custom_module_inits`).
    custom_inits: &str,
    runtime: EspRuntime,
) -> String {
    let configured: Vec<&Pin> = pins
        .iter()
        .filter(|p| !p.reserved && p.selected_function != PinFunction::Unset)
        .copied()
        .collect();

    if configured.is_empty() {
        return make_default_gen_section(clock, runtime);
    }

    // ── Feature flags ────────────────────────────────────────────────────────
    let has_output = configured
        .iter()
        .any(|p| p.selected_function == PinFunction::GpioOutput);
    let has_input = configured
        .iter()
        .any(|p| p.selected_function == PinFunction::GpioInput);
    let has_adc = configured
        .iter()
        .any(|p| matches!(p.selected_function, PinFunction::AdcChannel { .. }));
    let has_uart = configured.iter().any(|p| {
        matches!(
            p.selected_function,
            PinFunction::UsartTx(_) | PinFunction::UsartRx(_)
        )
    });
    let has_spi = configured.iter().any(|p| {
        matches!(
            p.selected_function,
            PinFunction::SpiSck(_)
                | PinFunction::SpiMosi(_)
                | PinFunction::SpiMiso(_)
                | PinFunction::SpiNss(_)
        )
    });
    let has_i2c = configured.iter().any(|p| {
        matches!(
            p.selected_function,
            PinFunction::I2cScl(_) | PinFunction::I2cSda(_)
        )
    });
    let has_twai = configured
        .iter()
        .any(|p| matches!(p.selected_function, PinFunction::CanTx | PinFunction::CanRx));
    let has_usb = configured
        .iter()
        .any(|p| matches!(p.selected_function, PinFunction::UsbDm | PinFunction::UsbDp));

    // ── use block ─────────────────────────────────────────────────────────────
    let use_block = build_use_block(
        has_output, has_input, has_adc, has_uart, has_spi, has_i2c, runtime,
    );

    // ── fn main() body ────────────────────────────────────────────────────────
    let mut body = String::new();
    body.push_str(&format!(
        "    let peripherals = {};\n",
        esp_init_line(clock)
    ));
    // Async: start the scheduler before anything awaits (or spawns).
    body.push_str(runtime.start_block());

    // ── GPIO Output / Input ───────────────────────────────────────────────────
    let outputs: Vec<&Pin> = configured
        .iter()
        .filter(|p| p.selected_function == PinFunction::GpioOutput)
        .copied()
        .collect();
    let inputs: Vec<&Pin> = configured
        .iter()
        .filter(|p| p.selected_function == PinFunction::GpioInput)
        .copied()
        .collect();

    if !outputs.is_empty() || !inputs.is_empty() {
        body.push('\n');
        body.push_str("    // ── GPIO ──\n");
        for p in &outputs {
            body.push_str(&format!(
                "    let mut {var} = Output::new(peripherals.{gpio}, Level::High, OutputConfig::default()); // GPIO Output\n",
                var = esp_binding(p),
                gpio = p.name,
            ));
        }
        for p in &inputs {
            body.push_str(&format!(
                "    let {var} = Input::new(peripherals.{gpio}, InputConfig::default()); // GPIO Input\n",
                var = esp_binding(p),
                gpio = p.name,
            ));
        }
    }

    // ── ADC — grouped by ADC instance ────────────────────────────────────────
    if has_adc {
        let mut adc_pins: BTreeMap<u8, Vec<&Pin>> = BTreeMap::new();
        for p in configured
            .iter()
            .filter(|p| matches!(p.selected_function, PinFunction::AdcChannel { .. }))
        {
            if let PinFunction::AdcChannel { adc, .. } = p.selected_function {
                adc_pins.entry(adc).or_default().push(p);
            }
        }

        for (adc_n, pin_list) in &adc_pins {
            body.push('\n');
            body.push_str(&format!("    // ── ADC{adc_n} ──\n"));
            body.push_str(&format!(
                "    let mut adc{adc_n}_config = AdcConfig::new();\n"
            ));
            for p in pin_list {
                if let PinFunction::AdcChannel { .. } = p.selected_function {
                    body.push_str(&format!(
                        "    let mut {var} = adc{adc_n}_config\
                         .enable_pin(peripherals.{gpio}, Attenuation::_11dB); // {label}\n",
                        var = esp_binding(p),
                        gpio = p.name,
                        label = p.selected_function.label(),
                    ));
                }
            }
            body.push_str(&format!(
                "    let mut _adc{adc_n} = Adc::new(peripherals.ADC{adc_n}, adc{adc_n}_config);\n"
            ));
        }
    }

    // ── Buses: bind the pins here, initialise in `pins/configs/<bus>.rs` ─────
    // Every wired pin keeps its OWN `let … = peripherals.GPIOn; // LABEL` line.
    // Two reasons: the canvas assignment stays visible where the user reads the
    // code, and it is the ONLY record a reopened project has — `parse_main_rs`
    // rebuilds the diagram from these lines (`mcu.config` stores no pin
    // functions). Moving them into the config module would lose the pins.
    for (label, calls) in bus_sections(&configured, usart, spi, i2c, runtime) {
        body.push('\n');
        body.push_str(&format!("    // ── {label} ──\n"));
        body.push_str(&calls);
    }

    // ── TWAI (CAN-compatible) — comment only ─────────────────────────────────
    if has_twai {
        let twai_tx = configured
            .iter()
            .find(|p| p.selected_function == PinFunction::CanTx);
        let twai_rx = configured
            .iter()
            .find(|p| p.selected_function == PinFunction::CanRx);
        body.push('\n');
        body.push_str("    // ── TWAI (CAN) — add esp-hal twai feature to Cargo.toml ──\n");
        if let Some(tx) = twai_tx {
            body.push_str(&format!("    // TX: peripherals.{}\n", tx.name));
        }
        if let Some(rx) = twai_rx {
            body.push_str(&format!("    // RX: peripherals.{}\n", rx.name));
        }
    }

    // ── USB — comment only (hardware-fixed on GPIO18/GPIO19) ─────────────────
    if has_usb {
        body.push('\n');
        body.push_str("    // ── USB — configured automatically by the USB peripheral ──\n");
    }

    // ── Custom modules ── last, after every binding/init they consume.
    if !custom_inits.is_empty() {
        body.push('\n');
        body.push_str("    // ── Custom modules ──\n");
        body.push_str(custom_inits);
    }

    // Blank line before GEN_END
    body.push('\n');

    format!(
        "{GEN_BEGIN}\n\
         {use_block}\
         {entry}\
         {body}\
         {GEN_END}\n",
        entry = runtime.entry(),
    )
}

// ── Default generated section (no pins configured yet) ────────────────────────

fn make_default_gen_section(clock: &ClockConfig, runtime: EspRuntime) -> String {
    format!(
        "{GEN_BEGIN}\n\
         {use_block}\
         {entry}\
             let peripherals = {init};\n\
         {start}\n\
             // Select pins in the MCU Configurator to generate code here.\n\
         {GEN_END}\n",
        use_block = build_use_block(false, false, false, false, false, false, runtime),
        entry = runtime.entry(),
        init = esp_init_line(clock),
        start = runtime.start_block(),
    )
}

// ── use block builder ─────────────────────────────────────────────────────────

fn build_use_block(
    has_output: bool,
    has_input: bool,
    has_adc: bool,
    has_uart: bool,
    has_spi: bool,
    has_i2c: bool,
    runtime: EspRuntime,
) -> String {
    let mut lines: Vec<String> = Vec::new();

    // Entry-point imports first (`Spawner`, the timer + software interrupt the
    // scheduler start consumes) — none on the blocking path.
    lines.extend(runtime.use_lines().iter().map(|s| (*s).to_owned()));

    // gpio — collect needed types alphabetically via BTreeSet
    let mut gpio_types: BTreeSet<&str> = BTreeSet::new();
    if has_output {
        gpio_types.insert("Level");
        gpio_types.insert("Output");
        gpio_types.insert("OutputConfig");
    }
    if has_input {
        gpio_types.insert("Input");
        gpio_types.insert("InputConfig");
        gpio_types.insert("Pull");
    }
    if !gpio_types.is_empty() {
        let types = gpio_types.iter().copied().collect::<Vec<_>>().join(", ");
        lines.push(format!("use esp_hal::gpio::{{{types}}};"));
    }

    if has_adc {
        lines.push("use esp_hal::analog::adc::{Adc, AdcConfig, Attenuation};".into());
    }
    // No bus imports: UART/SPI/I2C are built inside `pins/configs/<bus>.rs`, and
    // `main.rs` only hands them peripherals it already has in scope.
    let _ = (has_uart, has_spi, has_i2c);
    // No imports at all (blocking, and only USB/TWAI — which are comments —
    // selected): emit nothing rather than two stray blank lines above `fn main`.
    if lines.is_empty() {
        return String::new();
    }
    let mut block = lines.join("\n");
    block.push_str("\n\n");
    block
}

// ── Pin name → Rust variable name ────────────────────────────────────────────

/// Converts an ESP32 pin name to a snake_case variable name.
///
/// Examples:
/// - `"GPIO2"`  → `"gpio2"`
/// - `"GPIO20"` → `"gpio20"`
fn pin_var(pin_name: &str) -> String {
    pin_name.to_ascii_lowercase()
}

/// Binding (variable) name for a pin: `<gpio>_<type>[_<label>]`, e.g.
/// `gpio2_out`, `gpio0_adc1_in0`, or `gpio2_out_led` with a user label — the
/// ESP analogue of the STM32 `<pin>_<type>` format.
fn esp_binding(p: &Pin) -> String {
    pin_binding(&pin_var(&p.name), &p.selected_function, &p.custom_label)
}

/// The wired instances of each bus, as `(instance, signal → pin)` maps. One
/// pass over the pins instead of three near-identical ones.
type BusPins<'a> = BTreeMap<u8, BTreeMap<&'static str, &'a Pin>>;

fn collect_buses<'a>(configured: &[&'a Pin]) -> (BusPins<'a>, BusPins<'a>, BusPins<'a>) {
    let (mut uart, mut spi, mut i2c): (BusPins, BusPins, BusPins) = Default::default();
    for p in configured {
        let (bus, n, sig) = match p.selected_function {
            PinFunction::UsartRx(n) => (&mut uart, n, "rx"),
            PinFunction::UsartTx(n) => (&mut uart, n, "tx"),
            PinFunction::SpiSck(n) => (&mut spi, n, "sck"),
            PinFunction::SpiMosi(n) => (&mut spi, n, "mosi"),
            PinFunction::SpiMiso(n) => (&mut spi, n, "miso"),
            PinFunction::SpiNss(n) => (&mut spi, n, "cs"),
            PinFunction::I2cScl(n) => (&mut i2c, n, "scl"),
            PinFunction::I2cSda(n) => (&mut i2c, n, "sda"),
            _ => continue,
        };
        bus.entry(n).or_default().insert(sig, p);
    }
    (uart, spi, i2c)
}

/// `(instance, wired signals)` for each bus, in the order `init` takes them.
///
/// The SIGNALS matter as much as the instance: the generated `init` declares a
/// parameter per wired line, so a bus with no MISO gets a three-argument `init`
/// rather than one that ignores an argument — no unused-variable warnings in
/// the user's `main.rs`, and no pretending a pin is used when it is not. The
/// call site and the module are built from this same list, so they cannot
/// disagree.
pub fn bus_instances(configured: &[&Pin]) -> (BusWiring, BusWiring, BusWiring) {
    let (uart, spi, i2c) = collect_buses(configured);
    let flatten = |b: BusPins, order: &[&'static str]| -> BusWiring {
        b.into_iter()
            .map(|(n, pins)| {
                let sigs = order
                    .iter()
                    .filter(|s| pins.contains_key(*s))
                    .copied()
                    .collect();
                (n, sigs)
            })
            .collect()
    };
    (
        flatten(uart, UART_ORDER),
        flatten(spi, SPI_ORDER),
        flatten(i2c, I2C_ORDER),
    )
}

/// `(instance, signals)` pairs — see [`bus_instances`].
pub type BusWiring = Vec<(u8, Vec<&'static str>)>;

/// Signal order for each bus: the order the pins are bound in `main.rs` and
/// declared in the generated `init`. One definition, used by both.
pub const UART_ORDER: &[&str] = &["rx", "tx"];
pub const SPI_ORDER: &[&str] = &["sck", "mosi", "miso", "cs"];
pub const I2C_ORDER: &[&str] = &["scl", "sda"];

/// `(section label, body)` for every wired bus instance: one `let` per pin,
/// then the `pins::configs::<bus><n>::init(…)` call that consumes them.
///
/// Signals the canvas did not wire are simply absent — `init` takes only what
/// its template declares (SCK+MOSI for SPI, both lines for UART/I2C), so a
/// half-wired bus is reported as a TODO comment rather than emitting a call
/// that would not compile.
fn bus_sections(
    configured: &[&Pin],
    usart: &BTreeMap<u8, UsartModuleConfig>,
    spi_cfg: &BTreeMap<u8, SpiModuleConfig>,
    i2c_cfg: &BTreeMap<u8, I2cModuleConfig>,
    runtime: EspRuntime,
) -> Vec<(String, String)> {
    let (uart, spi, i2c) = collect_buses(configured);
    let mut out = Vec::new();
    // Async runtime → call the `init_async` twin, so the handles are the
    // `.await`-able esp-hal drivers. `init` stays in the file for a bus the user
    // would rather keep blocking; switching is a one-word edit here.
    let init_fn = if runtime == EspRuntime::Async {
        "init_async"
    } else {
        "init"
    };

    // One `let` per wired pin, in `init`'s parameter order, returning the
    // binding names to pass along.
    let section = |pins: &BTreeMap<&'static str, &Pin>,
                   order: &[&'static str],
                   handle: String,
                   module: String,
                   periph: String| {
        let mut body = String::new();
        let mut args = Vec::new();
        for sig in order.iter().filter(|s| pins.contains_key(*s)) {
            let p = pins[sig];
            let var = esp_binding(p);
            body.push_str(&format!(
                "    let {var} = peripherals.{gpio}; // {label}\n",
                gpio = p.name,
                label = p.selected_function.label(),
            ));
            args.push(var);
        }
        body.push_str(&format!(
            "    let mut {handle} = pins::configs::{module}::{init_fn}({periph}, {});\n",
            args.join(", ")
        ));
        body
    };

    for (n, pins) in &uart {
        let sfx = usart
            .get(n)
            .map(|c| module_label_sfx(&c.custom_label))
            .unwrap_or_default();
        out.push((
            format!("UART{n}"),
            section(
                pins,
                UART_ORDER,
                format!("_uart{n}{sfx}"),
                format!("uart{n}"),
                format!("peripherals.UART{n}"),
            ),
        ));
    }
    for (n, pins) in &spi {
        let sfx = spi_cfg
            .get(n)
            .map(|c| module_label_sfx(&c.custom_label))
            .unwrap_or_default();
        out.push((
            format!("SPI{n}"),
            section(
                pins,
                SPI_ORDER,
                format!("_spi{n}{sfx}"),
                format!("spi{n}"),
                format!("peripherals.SPI{n}"),
            ),
        ));
    }
    for (n, pins) in &i2c {
        let sfx = i2c_cfg
            .get(n)
            .map(|c| module_label_sfx(&c.custom_label))
            .unwrap_or_default();
        out.push((
            format!("I2C{n}"),
            section(
                pins,
                I2C_ORDER,
                format!("_i2c{n}{sfx}"),
                format!("i2c{n}"),
                format!("peripherals.I2C{n}"),
            ),
        ));
    }
    out
}

/// One `.with_xxx(peripherals.GPIOn)` link of an esp-hal builder chain, with the
/// pin's function named in a comment on its OWN line above the call. Empty when
/// the peripheral has no pin for that role.
///
/// The comment must NOT trail the call: the chain's terminating `;` is appended
/// after the LAST link, so a trailing `// …` swallows it and the generated file
/// stops parsing (`expected ';', found keyword 'loop'`).
fn with_pin(method: &str, pin: Option<&&Pin>) -> String {
    pin.map(|p| {
        format!(
            "\n        // {label}\n        .{method}(peripherals.{name})",
            label = p.selected_function.label(),
            name = p.name,
        )
    })
    .unwrap_or_default()
}

/// `_<sanitized label>` suffix for a module's generated handle (`_uart1_imu`),
/// or "" when the module has no user label. Mirror of `stm32::module_label_sfx`.
fn module_label_sfx(label: &str) -> String {
    let s = sanitize_label(label);
    if s.is_empty() {
        String::new()
    } else {
        format!("_{s}")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::panels::mcu_module::clock::graph::NodeState;
    use crate::panels::mcu_module::clock::graph::{GraphClock, esp32c3_graph, esp32c3_layout};
    use crate::panels::mcu_module::codegen::parse_mcu_id;

    fn esp_graph_clock() -> GraphClock {
        GraphClock {
            graph: esp32c3_graph(),
            layout: esp32c3_layout(),
        }
    }

    fn no_usart() -> BTreeMap<u8, UsartModuleConfig> {
        BTreeMap::new()
    }

    fn no_spi() -> BTreeMap<u8, SpiModuleConfig> {
        BTreeMap::new()
    }

    fn no_i2c() -> BTreeMap<u8, I2cModuleConfig> {
        BTreeMap::new()
    }

    /// The ESP CPU clock chosen in the diagram drives the generated
    /// `with_cpu_clock(...)` (bug: previously hardcoded to `max()`).
    #[test]
    fn default_cpu_clock_is_160mhz() {
        let code = fresh_esp32c3_main_rs(
            &[],
            &ClockConfig::Graph(esp_graph_clock()),
            "ESP32-C3",
            "esp32c3",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Blocking,
        );
        assert!(
            code.contains("CpuClock::_160MHz"),
            "default ESP CPU = 160 MHz:\n{code}"
        );
    }

    #[test]
    fn cpu_div6_emits_80mhz() {
        let mut gc = esp_graph_clock();
        gc.graph.node_mut("cpu_div").unwrap().state = NodeState::Index(1); // ÷6 → 80 MHz
        let code = fresh_esp32c3_main_rs(
            &[],
            &ClockConfig::Graph(gc),
            "ESP32-C3",
            "esp32c3",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Blocking,
        );
        assert!(
            code.contains("CpuClock::_80MHz"),
            "ESP CPU ÷6 = 80 MHz:\n{code}"
        );
        assert!(!code.contains("_160MHz"));
    }

    /// A chip with no modelled clock keeps the previous `max()` default.
    #[test]
    fn none_clock_falls_back_to_max() {
        let code = fresh_esp32c3_main_rs(
            &[],
            &ClockConfig::None,
            "ESP32-C3",
            "esp32c3",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Blocking,
        );
        assert!(code.contains("CpuClock::max()"), "{code}");
    }

    /// The MCU-id marker is emitted in the header and survives a re-splice, so a
    /// reopened project can restore the exact chip.
    #[test]
    fn id_marker_present_and_stable_across_update() {
        let fresh = fresh_esp32c3_main_rs(
            &[],
            &ClockConfig::None,
            "ESP32-C3",
            "esp32c3-graph",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Blocking,
        );
        assert_eq!(parse_mcu_id(&fresh).as_deref(), Some("esp32c3-graph"));
        let updated = update_esp32c3_main_rs(
            &fresh,
            &[],
            &ClockConfig::None,
            "ESP32-C3",
            "esp32c3-graph",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Blocking,
        );
        assert_eq!(parse_mcu_id(&updated).as_deref(), Some("esp32c3-graph"));
    }

    /// The provenance line names the REAL HAL version and runtime, and a
    /// re-splice refreshes it — including on a legacy file that still advertises
    /// the HAL its project was born with — without disturbing the user's own
    /// code above the markers.
    #[test]
    fn hal_header_line_tracks_version_and_runtime() {
        use crate::panels::mcu_module::project_gen::{ESP_HAL_REQ, ESP_RTOS_REQ};
        let hal = ESP_HAL_REQ.trim_start_matches(['~', '^', '=']);
        let blocking = fresh_esp32c3_main_rs(
            &[],
            &ClockConfig::None,
            "ESP32-C3",
            "esp32c3",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Blocking,
        );
        assert!(
            blocking.contains(&format!("// MCU: ESP32-C3 | HAL: esp-hal {hal} (blocking)")),
            "{blocking}"
        );

        // Legacy file: stale HAL line, a hand-added `use`, no id marker.
        let legacy = blocking
            .replace(
                &format!("// MCU: ESP32-C3 | HAL: esp-hal {hal} (blocking)\n"),
                "// MCU: ESP32-C3 | HAL: esp-hal 0.22\n",
            )
            .replace("#![no_std]", "use my_crate::thing;\n#![no_std]");
        let updated = update_esp32c3_main_rs(
            &legacy,
            &[],
            &ClockConfig::None,
            "ESP32-C3",
            "esp32c3",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Async,
        );
        assert!(
            updated.contains(&format!(
                "// MCU: ESP32-C3 | HAL: esp-hal {hal} + esp-rtos {ESP_RTOS_REQ} (async)"
            )),
            "stale line rewritten for the async runtime:\n{updated}"
        );
        assert!(!updated.contains("esp-hal 0.22"), "{updated}");
        assert_eq!(updated.matches("// MCU: ").count(), 1, "no duplicate");
        assert!(
            updated.contains("use my_crate::thing;"),
            "user code above the markers survives:\n{updated}"
        );
        // The line keeps its position (right under the banner), not appended.
        let banner = updated
            .find("// Auto-generated by Embedded IDE")
            .expect("banner");
        let mcu_line = updated.find("// MCU: ").expect("mcu line");
        assert!(banner < mcu_line && mcu_line < updated.find("#![no_std]").unwrap());

        // Idempotent — a second pass is a no-op.
        let again = update_esp32c3_main_rs(
            &updated,
            &[],
            &ClockConfig::None,
            "ESP32-C3",
            "esp32c3",
            &no_usart(),
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Async,
        );
        assert_eq!(again, updated, "re-splice must not churn the header");
    }

    /// Every bus builder chain must end in a bare `.with_xxx(...)` so its `;` is
    /// real code. The pin labels used to TRAIL the call — the terminating `;`
    /// landed inside that comment and the file stopped parsing
    /// ("expected `;`, found keyword `loop`"), on both runtimes.
    #[test]
    fn bus_chains_close_outside_the_pin_comments() {
        use crate::panels::mcu_module::pins::logic::pin::Pin;
        let pin = |num: usize, name: &str, f: PinFunction| {
            let mut p = Pin::new(num, name).with_functions(vec![f.clone()]);
            p.selected_function = f;
            p
        };
        let pins = [
            pin(28, "GPIO21", PinFunction::UsartTx(0)),
            pin(27, "GPIO20", PinFunction::UsartRx(0)),
            pin(9, "GPIO4", PinFunction::SpiSck(2)),
            pin(10, "GPIO5", PinFunction::SpiMosi(2)),
            pin(12, "GPIO6", PinFunction::SpiMiso(2)),
            pin(13, "GPIO7", PinFunction::SpiNss(2)),
            pin(14, "GPIO8", PinFunction::I2cScl(0)),
            pin(15, "GPIO9", PinFunction::I2cSda(0)),
        ];
        let refs: Vec<&Pin> = pins.iter().collect();

        for runtime in [EspRuntime::Blocking, EspRuntime::Async] {
            let code = fresh_esp32c3_main_rs(
                &refs,
                &ClockConfig::None,
                "ESP32-C3",
                "esp32c3",
                &no_usart(),
                &no_spi(),
                &no_i2c(),
                "",
                runtime,
            );
            for (i, line) in code.lines().enumerate() {
                if let Some((_, comment)) = line.split_once("//") {
                    assert!(
                        !comment.contains(';'),
                        "{runtime:?} line {}: `;` swallowed by a comment:\n{line}",
                        i + 1
                    );
                }
            }
            // Buses are no longer built here: main.rs binds the pins and calls
            // into `pins/configs/<bus>.rs` (see `codegen_esp_configs`).
            for head in ["Uart::new", "Spi::new", "I2c::new"] {
                assert!(
                    !code.contains(head),
                    "{runtime:?} builds {head} in main.rs, not in its config module:
{code}"
                );
            }
            // Async calls the `init_async` twin; Blocking the plain `init`.
            let init_fn = if runtime == EspRuntime::Async {
                "init_async"
            } else {
                "init"
            };
            for (module, periph) in [("uart0", "UART0"), ("spi2", "SPI2"), ("i2c0", "I2C0")] {
                let call = format!("pins::configs::{module}::{init_fn}(peripherals.{periph}");
                assert!(
                    code.contains(&call),
                    "{runtime:?} calls {call}:
{code}"
                );
            }
            // Every wired pin still has its own line — that is what a reopened
            // project reads back (see the round-trip test in `codegen::family`).
            for (var, gpio) in [
                ("gpio20_usart0_rx", "GPIO20"),
                ("gpio21_usart0_tx", "GPIO21"),
                ("gpio8_i2c0_scl", "GPIO8"),
            ] {
                assert!(
                    code.contains(&format!("let {var} = peripherals.{gpio};")),
                    "{runtime:?} binds {gpio}:
{code}"
                );
            }
        }
    }

    /// A wired _USART module sets the baud rate on the generated `Uart::new`.
    #[test]
    fn module_baud_drives_uart_config() {
        use crate::panels::mcu_module::pins::logic::pin::Pin;
        let mut tx = Pin::new(28, "GPIO21").with_functions(vec![PinFunction::UsartTx(0)]);
        tx.selected_function = PinFunction::UsartTx(0);
        let mut rx = Pin::new(27, "GPIO20").with_functions(vec![PinFunction::UsartRx(0)]);
        rx.selected_function = PinFunction::UsartRx(0);

        let mut usart = no_usart();
        let mut cfg = UsartModuleConfig::new(0);
        cfg.baud_rate = 9600;
        usart.insert(0, cfg);

        let code = fresh_esp32c3_main_rs(
            &[&tx, &rx],
            &ClockConfig::None,
            "ESP32-C3",
            "esp32c3",
            &usart,
            &no_spi(),
            &no_i2c(),
            "",
            EspRuntime::Blocking,
        );
        // The baud lives in the CONFIG MODULE now, not in main.rs — main.rs
        // only names the module. (The consts themselves are covered by
        // `codegen_esp_configs::tests::module_settings_land_inside_the_generated_block`.)
        assert!(
            code.contains("pins::configs::uart0::init(peripherals.UART0"),
            "main.rs calls the config module:
{code}"
        );
        assert!(
            !code.contains("with_baudrate"),
            "the baud is not in main.rs any more:
{code}"
        );
        // Both pins keep their own line, labelled — this is what a reopened
        // project parses back.
        assert!(code.contains("let gpio20_usart0_rx = peripherals.GPIO20; // USART0  RX"));
        assert!(code.contains("let gpio21_usart0_tx = peripherals.GPIO21; // USART0  TX"));
    }
}
